[X, Y] = meshgrid(1:5);
surf(X, Y, 1000*X.*Y)
zsecondarylabel('x1000 units')

figure
ax = axes;
h = plot(1:3);
c = allchild(ax);
disp(numel(c))
disp(c == h)

f = figure;
ax = axes;
h = plot(1:3);
disp(ancestor(h, 'axes') == ax)
disp(ancestor(h, 'figure') == f)

figure
ax = axes;
h = plot(1:3);
g = copyobj(h, ax);
disp(numel(allchild(ax)))

figure
ax = axes;
h = plot(1:3);
disp(numel(allchild(ax)))
delete(h)
disp(numel(allchild(ax)))

f = figure;
plot(1:3, 'Tag', 'a');
hold on
plot(3:-1:1, 'Tag', 'b');
h = findall(f, 'Type', 'line');
disp(numel(h))
disp(numel(findall(f, 'Tag', 'b')))

f = figure;
ax = axes;
